from decimal import Decimal
from typing import Any


def _numeric_line_no(value: Any) -> Decimal:
    """Return a numeric sort value using legacy empty-as-zero semantics."""
    if value is None:
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, (int, float)):
        return Decimal(str(value))
    text = str(value).strip()
    return Decimal(text) if text else Decimal(0)


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted order lines and renumber surviving lines per order."""
    surviving = [
        row for row in lines
        if row.get("DEL_FLG", "") != "Y"
    ]

    ordered = sorted(
        surviving,
        key=lambda row: (
            str(row.get("ORD_ID", "")),
            _numeric_line_no(row.get("LINE_NO", "")),
        ),
    )

    result: list[dict] = []
    current_order: str | None = None
    next_line_no = 1

    for row in ordered:
        order_id = str(row.get("ORD_ID", ""))
        if order_id != current_order:
            current_order = order_id
            next_line_no = 1

        copied = dict(row)
        copied["LINE_NO"] = next_line_no
        result.append(copied)
        next_line_no += 1

    return result
